mod solution;

fn main() {
    let cases = [
    (r#"values=[10,20,30,40]; choices=[0,1,1,3]"#, r#"40"#),
    (r#"values=[5,6,7]; choices=[0,0,2]"#, r#"7"#),
    (r#"
values=[5,6,7]; choices=[0,0,2]
"#, r#"7"#),
    (r#"  
values=[10,20,30,40]; choices=[0,1,1,3]
  "#, r#"40"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS reservoir-sampling");
}
